    // Halide layout: A(j, i) with j as x (columns), i as y (rows).
    Var j("j"), i("i");

    Func init_A("init_A"), init_R("init_R"), init_Q("init_Q");

    Expr i_e = i;
    Expr j_e = j;
    Expr m_e = m;

