    init_A(j, i) = a_val;
    init_Q(j, i) = cast<num_t>(0);

    // R is N x N, initialized to 0
    Var jj("jj"), ii("ii");
    init_R(jj, ii) = cast<num_t>(0);

    init_A.realize(A);
    init_Q.realize(Q);
    init_R.realize(R);
}

int main(int argc, char *argv[]) {
    // Problem size
    int m = M;
    int n = N;

    // Buffers:
    // C layout: A[m][n], Q[m][n], R[n][n]
    // Halide layout: first dim = column (j or k), second dim = row (i)
    Halide::Buffer<num_t, 2> A_curr(n, m);
    Halide::Buffer<num_t, 2> Q_curr(n, m);
    Halide::Buffer<num_t, 2> R_curr(n, n);

    Halide::Buffer<num_t, 2> A_next(n, m);
    Halide::Buffer<num_t, 2> Q_next(n, m);
    Halide::Buffer<num_t, 2> R_next(n, n);

    // Initialize arrays
    init_array(m, n, A_curr, R_curr, Q_curr);

    // Halide parameters representing the current state
    ImageParam A_prev(type_of<num_t>(), 2, "A_prev");
    ImageParam Q_prev(type_of<num_t>(), 2, "Q_prev");
    ImageParam R_prev(type_of<num_t>(), 2, "R_prev");

    // Scalar parameters: current column k and R[k][k]
    Param<int>  k_param("k");
    Param<num_t> Rkk_param("Rkk");

    A_prev.set(A_curr);
    Q_prev.set(Q_curr);
    R_prev.set(R_curr);

    // Common Vars
    Var x("x"), y("y");

    // ------------------------------------------------------------------
    // Step 1: compute nrm = sum_i A[i][k]^2 using Halide reduction
    // ------------------------------------------------------------------
    RDom r_m(0, m, "r_m");

    Func nrm("nrm");
    nrm() = cast<num_t>(0);
    nrm() += A_prev(k_param, r_m) * A_prev(k_param, r_m);

    // ------------------------------------------------------------------
    // Step 2-4: given nrm (and thus Rkk), update Q, R, and A for column k
    //
    // We construct a per-column transformation:
    //   - q_col(i) = A_prev(i, k) / Rkk
    //   - R_row(j) = sum_i q_col(i) * A_prev(i, j)
    //   - Q_next(i, j):
    //        if j == k: q_col(i)
    //        else:      Q_prev(i, j)
    //   - R_next(k, k) = Rkk
    //     R_next(k, j>k) = R_row(j)
    //     all other R entries unchanged
    //   - A_next(i, j>k) = A_prev(i, j) - q_col(i) * R_row(j)
    //     A_next(i, j<=k) = A_prev(i, j)
    // ------------------------------------------------------------------

    // q_col: normalized k-th column of A_prev
    Var i("i");
    Func q_col("q_col");
    q_col(i) = A_prev(k_param, i) / Rkk_param;

    // R_row(j): dot product of q_col and A_prev(:, j)
    RDom r2(0, m, "r2");
    Func R_row("R_row");
    R_row(x) = cast<num_t>(0);
    R_row(x) += q_col(r2) * A_prev(x, r2);

    // Q_next
    Func Q_next_func("Q_next");
    Q_next_func(x, y) = select(x == k_param, q_col(y), Q_prev(x, y));

    // R_next
    Func R_next_func("R_next");
    Expr is_diag      = (x == k_param) && (y == k_param);
    Expr is_rowk_off  = (y == k_param) && (x > k_param);
    R_next_func(x, y) =
        select(is_diag, Rkk_param,
               select(is_rowk_off, R_row(x), R_prev(x, y)));

    // A_next
    Func A_next_func("A_next");
    Expr update_col = x > k_param;
    A_next_func(x, y) =
        select(update_col,
               A_prev(x, y) - q_col(y) * R_row(x),
               A_prev(x, y));

    // Simple schedules to keep row-major traversal (y outer, x inner)
    A_next_func.reorder(x, y);
    Q_next_func.reorder(x, y);
    R_next_func.reorder(x, y);

    // Build a pipeline for the three outputs (A_next, Q_next, R_next)
    std::vector<Func> outputs = {A_next_func, Q_next_func, R_next_func};
    Pipeline gram_step(outputs);

    // JIT-compile once (nrm and the per-step pipeline)
    nrm.compile_jit();
    gram_step.compile_jit();

    // ------------------------------------------------------------------
    // Run the Gram-Schmidt kernel (outer loop over k) and time it
    // ------------------------------------------------------------------
    using clock = std::chrono::high_resolution_clock;

    auto start = clock::now();

    for (int k = 0; k < n; ++k) {
        // Bind the current state
        A_prev.set(A_curr);
        Q_prev.set(Q_curr);
        R_prev.set(R_curr);

        k_param.set(k);

        // Compute nrm for this column
        Halide::Buffer<num_t> nrm_buf = nrm.realize();
        num_t nrm_val = nrm_buf();

        // R[k][k] = sqrt(nrm)
        num_t Rkk_val = static_cast<num_t>(std::sqrt(static_cast<double>(nrm_val)));
        Rkk_param.set(Rkk_val);

        // Run the per-column update to produce A_next, Q_next, R_next
        Realization r({A_next, Q_next, R_next});
        gram_step.realize(r);

        // Swap current and next for the next iteration
        std::swap(A_curr, A_next);
        std::swap(Q_curr, Q_next);
        std::swap(R_curr, R_next);
    }

    auto end = clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // ------------------------------------------------------------------
    // Print results (R and Q) to prevent dead-code elimination
    // ------------------------------------------------------------------
    using namespace std::string_literals;

    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print R (original order: R[i][j], i in [0,n), j in [0,n))
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // C layout R[i][j] -> Halide layout R_curr(j, i)
                std::cerr << R_curr(j, i) << '\n';
            }
        }

        // Print Q (original order: Q[i][j], i in [0,m), j in [0,n))
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                // C layout Q[i][j] -> Halide layout Q_curr(j, i)
                std::cerr << Q_curr(j, i) << '\n';
            }
        }
    }

    // Print timing (seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
