#include <iostream>

#include "Halide.h"

// Common PolyBench-style definitions (DATA_TYPE, M, N, etc.)
#include "defines.hpp"

// Benchmark-specific definitions (M, N, DATA_TYPE for gramschmidt)
#include "gramschmidt.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize A, R, Q as in the original PolyBench C code.
 *
 * C layout:
 *   A[m][n], R[n][n], Q[m][n]
 *
 * Halide layout:
 *   Buffer<num_t,2> A(n, m) stores A[i][j] at A(j, i)
 *   Buffer<num_t,2> R(n, n) stores R[i][j] at R(j, i)
 *   Buffer<num_t,2> Q(n, m) stores Q[i][j] at Q(j, i)
 */
static void init_array(int m, int n,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> R,
                       Halide::Buffer<num_t, 2> Q) {
    Var i("i"), j("j");

    // Initialize A and Q.
    // Original C:
    // for (i = 0; i < m; i++)
    //   for (j = 0; j < n; j++) {
    //     A[i][j] = ((( (i*j) % m) / m )*100) + 10;
    //     Q[i][j] = 0.0;
    //   }
    Func init_A("init_A"), init_Q("init_Q");

    // Halide indices: A(j, i) == A[i][j] in C
    Expr val_A = (i * j) % m;
    init_A(j, i) = (cast<num_t>(val_A) / cast<num_t>(m)) * cast<num_t>(100) + cast<num_t>(10);
    init_Q(j, i) = cast<num_t>(0);

    init_A.realize(A);
    init_Q.realize(Q);

    // Initialize R to 0.
    // Original C:
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < n; j++)
    //     R[i][j] = 0.0;
    Func init_R("init_R");
    init_R(j, i) = cast<num_t>(0);
    init_R.realize(R);
}

int main(int argc, char *argv[]) {
    // Problem size (from PolyBench-style headers)
    int m = M;
    int n = N;

    // Buffers for A, R, Q.
    // Mapping: A(i,j) in C => A_buf(j,i) in Halide.
    Halide::Buffer<num_t, 2> A_curr(n, m);  // columns x = 0..n-1, rows y = 0..m-1
    Halide::Buffer<num_t, 2> R_curr(n, n);  // R[i][j] -> R_curr(j, i)
    Halide::Buffer<num_t, 2> Q_curr(n, m);  // Q[i][j] -> Q_curr(j, i)

    // Scratch buffers for double buffering A and R.
    Halide::Buffer<num_t, 2> A_next(n, m);
    Halide::Buffer<num_t, 2> R_next(n, n);

    // Initialize arrays.
    init_array(m, n, A_curr, R_curr, Q_curr);

    // -----------------------------
    // Build Halide pipelines
    // -----------------------------

    // Common parameters: current A and R, column index k, and current q column.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam R_param(type_of<num_t>(), 2, "R_param");
    ImageParam q_param(type_of<num_t>(), 1, "q_param");   // length m, stores q_k (the k-th column of Q)
    Param<int> k_param("k_param");
    Param<num_t> diag_param("diag_param");                 // R[k][k]

    Var x("x"), y("y");

    // 1) Pipeline to compute the squared norm of column k of A:
    //
    // nrm = sum_{i=0..m-1} A[i][k]^2
    //
    // With our layout, A[i][k] == A_param(k, i).
    RDom r_norm(0, m, "r_norm");
    Func nrm_func("nrm_func");
    nrm_func() = cast<num_t>(0);
    nrm_func() += A_param(k_param, r_norm) * A_param(k_param, r_norm);

    // 2) Pipeline to compute the k-th column of Q: q_col(i) = A[i][k] / diag.
    //
    // A[i][k] == A_param(k_param, i).
    Var i_var("i_var");
    Func q_col("q_col");
    q_col(i_var) = A_param(k_param, i_var) / diag_param;

    // 3) Pipeline to update A and R given q_col and k.
    //
    // For each k:
    //   R[k][j]      = sum_i q[i]*A[i][j]  for j > k  (dot product)
    //   A[i][j]      = A[i][j] - q[i]*R[k][j] for j > k
    //   R[k][k]      already set on host
    //
    // In Halide coordinates:
    //   A(i,j) in C -> A_param(x=j, y=i)
    //   R(i,j) in C -> R_param(x=j, y=i)
    //
    // We'll compute:
    //   R_row(x) = sum_{i} q_param(i) * A_param(x, i)   (for all x, but we will only use x > k)
    //   A_next(x,y) = A_param(x,y)                if x <= k
    //               = A_param(x,y) - q_param(y)*R_row(x)  if x > k
    //
    //   R_next(x,y) = R_param(x,y)                       if y != k or x <= k
    //               = R_row(x)                           if y == k and x > k
    //
    RDom r_update(0, m, "r_update");

    Func R_row("R_row");
    R_row(x) = cast<num_t>(0);
    R_row(x) += q_param(r_update) * A_param(x, r_update);

    Func A_next_func("A_next_func");
    A_next_func(x, y) = select(x <= k_param,
                               A_param(x, y),
                               A_param(x, y) - q_param(y) * R_row(x));

    Func R_next_func("R_next_func");
    R_next_func(x, y) = select((y == k_param) && (x > k_param),
                               R_row(x),
                               R_param(x, y));

    // Build a Pipeline for the update of A and R.
    Pipeline update_pipeline({A_next_func, R_next_func});

    // JIT-compile all of the above Halide code once.
    nrm_func.compile_jit();
    q_col.compile_jit();
    update_pipeline.compile_jit();

    // -----------------------------
    // Main computation (Gram-Schmidt)
    // -----------------------------

    auto start = std::chrono::high_resolution_clock::now();

    // Iterative Modified Gram-Schmidt:
    // for (k = 0; k < n; k++) {
    //   nrm = sum_i A[i][k]^2;
    //   R[k][k] = sqrt(nrm);
    //   Q[i][k] = A[i][k] / R[k][k];
    //   for (j = k+1; j < n; j++) {
    //     R[k][j] = sum_i Q[i][k]*A[i][j];
    //     A[i][j] = A[i][j] - Q[i][k]*R[k][j];
    //   }
    // }
    //
    // We express:
    //  - the reduction over i for the norm using nrm_func
    //  - the Q column computation using q_col
    //  - the (j,i) updates of A and R using update_pipeline
    //
    for (int k = 0; k < n; k++) {
        // Bind current A and R to the ImageParams for this iteration.
        A_param.set(A_curr);
        R_param.set(R_curr);
        k_param.set(k);

        // 1) Compute the squared norm of column k.
        Halide::Buffer<num_t> nrm_buf = nrm_func.realize({});
        num_t nrm_value = nrm_buf();
        // Compute R[k][k] = sqrt(nrm).
        double diag_double = std::sqrt(static_cast<double>(nrm_value));
        num_t diag_value = static_cast<num_t>(diag_double);

        // 2) Compute the k-th column of Q using Halide.
        diag_param.set(diag_value);
        Halide::Buffer<num_t> q_col_buf(m);
        q_col.realize(q_col_buf);

        // 3) Write Q[i][k] on the host and set R[k][k].
        // Mapping: Q[i][k] in C -> Q_curr(k, i) in Halide.
        for (int i = 0; i < m; i++) {
            Q_curr(k, i) = q_col_buf(i);
        }
        // R[k][k] in C -> R_curr(k, k) in Halide (x = k, y = k).
        R_curr(k, k) = diag_value;

        // 4) Use update_pipeline to update A and R for all j > k.
        q_param.set(q_col_buf);
        A_param.set(A_curr);
        R_param.set(R_curr);
        k_param.set(k);

        // Realize both A_next_func and R_next_func into A_next and R_next.
        update_pipeline.realize(A_next, R_next);

        // Swap current and next for the next iteration.
        std::swap(A_curr, A_next);
        std::swap(R_curr, R_next);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -----------------------------
    // Optional: print R and Q (for checking / preventing DCE)
    // -----------------------------
    // Layout reminder:
    //   R[i][j] in C -> R_curr(j, i)
    //   Q[i][j] in C -> Q_curr(j, i)

    std::cerr << std::fixed << std::setprecision(2);

    std::cerr << "R:\n";
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            std::cerr << R_curr(j, i) << ' ';
        }
        std::cerr << '\n';
    }

    std::cerr << "Q:\n";
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            std::cerr << Q_curr(j, i) << ' ';
        }
        std::cerr << '\n';
    }

    // -----------------------------
    // Print timing result (seconds)
    // -----------------------------
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
