#include <chrono>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (e.g. DATA_TYPE, M, N)
#include "defines.hpp"

// include benchmark-specific definitions (mirroring gramschmidt.h)
#include "gramschmidt.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A, R, Q as in the original C code.
 *
 * C layout:
 *   A[m][n], R[n][n], Q[m][n]
 *
 * Halide layout:
 *   Buffer<num_t,2> A(n, m); // A(x=j, y=i) == A[i][j] in C
 *   Buffer<num_t,2> R(n, n); // R(x=j, y=i) == R[i][j] in C
 *   Buffer<num_t,2> Q(n, m); // Q(x=j, y=i) == Q[i][j] in C
 */
static void init_array(int m, int n,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> R,
                       Halide::Buffer<num_t, 2> Q) {
    Var x("x"), y("y");

    Func init_A("init_A"), init_Q("init_Q"), init_R("init_R");

    // A[i][j] = (((i*j) % m) / m) * 100 + 10;
    // C row i -> y, col j -> x
    init_A(x, y) =
        cast<num_t>(((y * x) % m)) / cast<num_t>(m) * cast<num_t>(100) + cast<num_t>(10);

    // Q[i][j] = 0.0
    init_Q(x, y) = cast<num_t>(0);

    // R[i][j] = 0.0
    init_R(x, y) = cast<num_t>(0);

    // Realize into the provided buffers.
    init_A.realize(A);
    init_Q.realize(Q);
    init_R.realize(R);
}

int main(int argc, char *argv[]) {
    // Problem size
    int m = M;
    int n = N;

    // Buffers: x = column index, y = row index
    Halide::Buffer<num_t, 2> A(n, m); // A(i,j) in C -> A(j,i) here
    Halide::Buffer<num_t, 2> R(n, n); // R(i,j) in C -> R(j,i) here
    Halide::Buffer<num_t, 2> Q(n, m); // Q(i,j) in C -> Q(j,i) here

    // Initialize data
    init_array(m, n, A, R, Q);

    // Create Halide parameters and Funcs to express the per-column and per-dot operations.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam Q_param(type_of<num_t>(), 2, "Q_param");

    // Column indices and scalars as runtime parameters.
    Param<int> col_k("col_k");      // current k (column index)
    Param<int> col_j("col_j");      // current j (column index)
    Param<num_t> rkk_param("rkk");  // R[k][k]
    Param<num_t> rkj_param("rkj");  // R[k][j]

    // Bind initial buffers
    A_param.set(A);
    Q_param.set(Q);

    // Vars and reduction domains
    Var i("i");
    RDom r_i(0, m, "r_i");  // sum over rows (i from 0 to m-1)

    // 1) Compute the squared norm of column k of A:
    //
    //    nrm = sum_i A[i][k]^2
    //
    //    In Halide: A_param(col_k, i) corresponds to A[i][col_k].
    Func col_norm("col_norm");
    col_norm() = cast<num_t>(0);
    col_norm() += A_param(col_k, r_i) * A_param(col_k, r_i);

    // 2) Given R[k][k] in rkk_param, compute the normalized column:
    //
    //    Q[i][k] = A[i][k] / R[k][k]
    //
    // We compute just the column as a 1D Func over i.
    Func q_col("q_col");
    q_col(i) = A_param(col_k, i) / rkk_param;

    // 3) For given k and j, compute:
    //
    //    R[k][j] = sum_i Q[i][k] * A[i][j]
    //
    RDom r_i2(0, m, "r_i2");
    Func dot("dot");
    dot() = cast<num_t>(0);
    dot() += Q_param(col_k, r_i2) * A_param(col_j, r_i2);

    // 4) For given k, j and rkj, update column j of A:
    //
    //    A[i][j] = A[i][j] - Q[i][k] * R[k][j]
    //
    Func update_col("update_col");
    update_col(i) = A_param(col_j, i) - Q_param(col_k, i) * rkj_param;

    // Compile the small Halide pipelines ahead of timing.
    col_norm.compile_jit();
    q_col.compile_jit();
    dot.compile_jit();
    update_col.compile_jit();

    // Time just the main Gram-Schmidt kernel, not initialization or compilation.
    auto start = std::chrono::high_resolution_clock::now();

    // Host-driven outer loops (k and j) to respect loop-carried dependencies.
    for (int k = 0; k < n; ++k) {
        col_k.set(k);

        // ------------------------------------------------------------
        // Step 1: Compute nrm = sum_i A[i][k]^2 and R[k][k] = sqrt(nrm)
        // ------------------------------------------------------------
        {
            Halide::Buffer<num_t> nrm_buf = col_norm.realize();
            num_t nrm = nrm_buf(); // scalar buffer

            // SQRT_FUN(nrm) in the original C; use std::sqrt here.
            num_t rkk = static_cast<num_t>(std::sqrt(static_cast<double>(nrm)));
            rkk_param.set(rkk);

            // Store R[k][k]; mapping R[i][j] -> R(j,i)
            R(k, k) = rkk;
        }

        // ------------------------------------------------------------
        // Step 2: Compute Q[i][k] = A[i][k] / R[k][k]
        // ------------------------------------------------------------
        {
            Halide::Buffer<num_t> qbuf(m); // 1D over rows
            q_col.realize(qbuf);

            for (int i_row = 0; i_row < m; ++i_row) {
                // Q[i][k] -> Q(k, i)
                Q(k, i_row) = qbuf(i_row);
            }
        }

        // Q has been updated; Q_param should see the new data automatically
        // since it wraps the same underlying buffer.

        // ------------------------------------------------------------
        // Step 3: For j = k+1..n-1, compute R[k][j] and update A[:, j]
        // ------------------------------------------------------------
        for (int j = k + 1; j < n; ++j) {
            col_j.set(j);

            // Compute R[k][j] = sum_i Q[i][k] * A[i][j]
            Halide::Buffer<num_t> r_buf = dot.realize();
            num_t rkj = r_buf();
            rkj_param.set(rkj);

            // Store R[k][j]; mapping R[i][j] -> R(j,i)
            R(j, k) = rkj;

            // Update A[i][j] = A[i][j] - Q[i][k] * R[k][j]
            Halide::Buffer<num_t> updated_col(m);
            update_col.realize(updated_col);

            for (int i_row = 0; i_row < m; ++i_row) {
                // A[i][j] -> A(j, i)
                A(j, i_row) = updated_col(i_row);
            }
        }

        // A_param and Q_param continue to reference A and Q,
        // which now contain the updated values for the next k.
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional debug output (similar in spirit to print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        std::cerr << "R matrix:\n";
        for (int i_row = 0; i_row < n; ++i_row) {
            for (int j_col = 0; j_col < n; ++j_col) {
                // R[i][j] -> R(j,i)
                std::cerr << R(j_col, i_row) << '\n';
            }
        }

        std::cerr << "Q matrix:\n";
        for (int i_row = 0; i_row < m; ++i_row) {
            for (int j_col = 0; j_col < n; ++j_col) {
                // Q[i][j] -> Q(j,i)
                std::cerr << Q(j_col, i_row) << '\n';
            }
        }
    }

    // Print just the kernel time in seconds, as in the example.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
