    init_Q(j, i) = cast<num_t>(0);

    // R[i][j] = 0.0;
    init_R(j, i) = cast<num_t>(0);

    init_A.realize(A);
    init_Q.realize(Q);
    init_R.realize(R);
}

int main(int argc, char *argv[]) {
    // Problem size (compile-time constants from gramschmidt.hpp)
    int m = M;
    int n = N;

    // Buffers:
    // A is MxN in C => Buffer(n, m) and accessed as A(j, i)
    // R is NxN in C => Buffer(n, n) and accessed as R(j, i)
    // Q is MxN in C => Buffer(n, m) and accessed as Q(j, i)
    Buffer<num_t, 2> A(n, m);
    Buffer<num_t, 2> R(n, n);
    Buffer<num_t, 2> Q(n, m);

    // Initialize data
    init_array(m, n, A, R, Q);

    // ------------------------------------------------------------------------
    // Build Halide pipelines for per-k steps of Modified Gram-Schmidt
    // ------------------------------------------------------------------------

    // Parameters for the current iteration
    Param<int> k_param("k");          // current column k
    Param<num_t> Rkk_param("Rkk");    // R[k][k] value

    // ImageParams for current state of A, Q, and the row R[k][*]
    ImageParam A_param(type_of<num_t>(), 2, "A_param");        // (x=j, y=i)
    ImageParam Q_param(type_of<num_t>(), 2, "Q_param");        // (x=j, y=i)
    ImageParam Rk_row_param(type_of<num_t>(), 1, "Rk_row");    // R[k][j] as 1-D over j

    Var i("i"), j("j");

    // 1) Compute nrm = sum_i A[i][k]*A[i][k]
    //    A[i][k] in C => A_param(k_param, i) here
    RDom ri(0, m, "ri");
    Func nrm_func("nrm_func");
    nrm_func() = cast<num_t>(0);
    nrm_func() += A_param(k_param, ri) * A_param(k_param, ri);

    // 2) Compute column k of Q:
    //    Q[i][k] = A[i][k] / R[k][k]
    //    We compute a 1-D Func over i, then copy into Q buffer.
    Func Q_col("Q_col");
    Q_col(i) = A_param(k_param, i) / Rkk_param;

    // 3) Compute row k of R for all columns j:
    //    R[k][j] = sum_i Q[i][k] * A[i][j]
    //    Q[i][k] => Q_param(k_param, i)
    //    A[i][j] => A_param(j, i)
    RDom ri2(0, m, "ri2");
    Func R_row("R_row");
    R_row(j) = cast<num_t>(0);
    R_row(j) += Q_param(k_param, ri2) * A_param(j, ri2);

    // 4) Update A for columns j > k:
    //    A[i][j] = A[i][j] - Q[i][k] * R[k][j]
    //    A[i][j] => A_param(j, i)
    //    Q[i][k] => Q_param(k_param, i)
    //    R[k][j] => Rk_row_param(j)
    Func A_next("A_next");
    A_next(j, i) = select(j > k_param,
                          A_param(j, i) -
                              Q_param(k_param, i) * Rk_row_param(j),
                          A_param(j, i));

    // Simple (optional) schedules: compute everything at root
    nrm_func.compute_root();
    Q_col.compute_root();
    R_row.compute_root();
    A_next.compute_root();

    Target target = get_jit_target_from_environment();
    nrm_func.compile_jit(target);
    Q_col.compile_jit(target);
    R_row.compile_jit(target);
    A_next.compile_jit(target);

    // Pre-allocate intermediate buffers to avoid per-iteration allocation
    Buffer<num_t> nrm_buf;           // 0-D: scalar
    Buffer<num_t> Q_col_buf(m);      // 1-D over i
    Buffer<num_t> R_row_buf(n);      // 1-D over j
    Buffer<num_t, 2> A_next_buf(n, m);

    // ------------------------------------------------------------------------
    // Run the Modified Gram-Schmidt algorithm, driving the outer loop in C++
    // ------------------------------------------------------------------------

    auto start = std::chrono::high_resolution_clock::now();

    for (int k = 0; k < n; ++k) {
        // Bind current matrices to ImageParams
        A_param.set(A);
        Q_param.set(Q);
        k_param.set(k);

        // 1) Compute nrm for column k
        nrm_func.realize(nrm_buf);
        num_t nrm = nrm_buf();

        // 2) R[k][k] = sqrt(nrm)
        num_t Rkk = std::sqrt(nrm);
        R(k, k) = Rkk;

        // 3) Compute column k of Q
        Rkk_param.set(Rkk);
        Q_col.realize(Q_col_buf);
        for (int ii = 0; ii < m; ++ii) {
            // Q[i][k] in C => Q(k, ii) here (x = column k, y = row i)
            Q(k, ii) = Q_col_buf(ii);
        }

        // Update Q_param now that Q column k is valid
        Q_param.set(Q);

        // 4) Compute row k of R for all j
        R_row.realize(R_row_buf);
        for (int jj = k + 1; jj < n; ++jj) {
            // R[k][j] in C => R(jj, k) here (x = column j, y = row k)
            R(jj, k) = R_row_buf(jj);
        }

        // 5) Update A for columns j > k
        Rk_row_param.set(R_row_buf);
        A_next.realize(A_next_buf);

        // Copy A_next back into A for the next iteration
        A.copy_from(A_next_buf);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // ------------------------------------------------------------------------
    // Print results (R and Q) if desired, to prevent dead-code elimination
    // ------------------------------------------------------------------------
    using namespace std::string_literals;

    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print R (NxN)
        for (int i = 0; i < n; i++) {
            for (int j2 = 0; j2 < n; j2++) {
                // R[i][j] in C => R(j, i) here
                std::cerr << R(j2, i) << '\n';
            }
        }

        // Print Q (MxN)
        for (int i = 0; i < m; i++) {
            for (int j2 = 0; j2 < n; j2++) {
                // Q[i][j] in C => Q(j, i) here
                std::cerr << Q(j2, i) << '\n';
            }
        }
    }

    // Print timing in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
