#include <chrono>
#include <cmath>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// include common definitions (DATA_TYPE, SCALAR_VAL, SQRT_FUN, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (M, N)
#include "gramschmidt.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/*
 * Array initialization: matches the original C init_array.
 *
 * C code:
 *   for (i = 0; i < m; i++)
 *     for (j = 0; j < n; j++) {
 *       A[i][j] = (((DATA_TYPE) ((i*j) % m) / m )*100) + 10;
 *       Q[i][j] = 0.0;
 *     }
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       R[i][j] = 0.0;
 *
 * Mapping to Halide:
 *   - C arrays A[m][n] --> Buffer A(n, m)   (x = j, y = i)
 *   - C arrays Q[m][n] --> Buffer Q(n, m)
 *   - C arrays R[n][n] --> Buffer R(n, n)
 */
static void init_array(int m, int n,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> R,
                       Halide::Buffer<num_t, 2> Q) {
    Var i("i"), j("j");

    Func init_A("init_A"), init_Q("init_Q"), init_R("init_R");

    // A[i][j] = (((DATA_TYPE) ((i*j) % m) / m )*100) + 10;
    // Remember: A(j, i) corresponds to A[i][j].
    Expr ii = i;
    Expr jj = j;
    Expr val = cast<num_t>((ii * jj) % m) / cast<num_t>(m);
    val = val * cast<num_t>(100) + cast<num_t>(10);
    init_A(j, i) = val;

    // Q[i][j] = 0.0;
    init_Q(j, i) = cast<num_t>(0);

    // R[i][j] = 0.0;
    init_R(j, i) = cast<num_t>(0);

    // Realize into the supplied buffers.
    init_A.realize(A);
    init_Q.realize(Q);
    init_R.realize(R);
}

int main(int argc, char *argv[]) {
    // Problem size
    int m = M;
    int n = N;

    // Buffers:
    //   C A[m][n] -> Buffer A(n, m)  (x = column j, y = row i)
    //   C Q[m][n] -> Buffer Q(n, m)
    //   C R[n][n] -> Buffer R(n, n)
    Halide::Buffer<num_t, 2> A(n, m);
    Halide::Buffer<num_t, 2> Q(n, m);
    Halide::Buffer<num_t, 2> R(n, n);

    // Initialize data
    init_array(m, n, A, R, Q);

    // ------------------------------------------------------------------------
    // Build Halide helpers for the Gram-Schmidt kernel.
    //
    // Original kernel:
    //
    // for (k = 0; k < N; k++) {
    //   nrm = 0;
    //   for (i = 0; i < M; i++)
    //     nrm += A[i][k] * A[i][k];
    //   R[k][k] = sqrt(nrm);
    //   for (i = 0; i < M; i++)
    //     Q[i][k] = A[i][k] / R[k][k];
    //   for (j = k+1; j < N; j++) {
    //     R[k][j] = 0;
    //     for (i = 0; i < M; i++)
    //       R[k][j] += Q[i][k] * A[i][j];
    //     for (i = 0; i < M; i++)
    //       A[i][j] -= Q[i][k] * R[k][j];
    //   }
    // }
    //
    // We keep the outer loops over k and j on the host (loop-carried
    // dependences), and use Halide to implement the inner computations
    // over i via small pipelines.
    // ------------------------------------------------------------------------

    // Image parameters for current A and Q.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam Q_param(type_of<num_t>(), 2, "Q_param");

    // Scalar parameters controlling the column indices and scalars.
    Param<int>   k_param("k");
    Param<int>   j_param("j");
    Param<num_t> rkk_param("rkk");
    Param<num_t> rkj_param("rkj");

    // Variable and reduction domains over rows i = 0..m-1.
    Var i("i");
    RDom r_i(0, m, "r_i");
    RDom r_i2(0, m, "r_i2");

    // 1) Compute column norm: nrm = sum_i A[i][k]^2
    //    col_sumsq() is a 0-dimensional Func (a scalar).
    Func col_sumsq("col_sumsq");
    col_sumsq() = cast<num_t>(0);
    // A[i][k] -> A_param(k, i)
    col_sumsq() += A_param(k_param, r_i) * A_param(k_param, r_i);

    // 2) Compute Q[:,k] = A[:,k] / R[k][k]
    //    q_col(i) gives Q[i][k] for each i.
    Func q_col("q_col");
    q_col(i) = A_param(k_param, i) / rkk_param;

    // 3) Compute R[k][j] as dot product Q[:,k]^T * A[:,j].
    Func dot_col("dot_col");
    dot_col() = cast<num_t>(0);
    dot_col() += Q_param(k_param, r_i2) * A_param(j_param, r_i2);

    // 4) Update A[:,j] = A[:,j] - Q[:,k] * R[k][j]
    Func update_col("update_col");
    update_col(i) = A_param(j_param, i) - Q_param(k_param, i) * rkj_param;

    // Compile all helper pipelines ahead of timing.
    col_sumsq.compile_jit();
    q_col.compile_jit();
    dot_col.compile_jit();
    update_col.compile_jit();

    // ------------------------------------------------------------------------
    // Execute kernel and measure time.
    // ------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Outer loop over k (host-driven, to respect loop-carried dependences).
    for (int k = 0; k < n; ++k) {
        // Bind current A and k, then compute norm of column k.
        A_param.set(A);
        k_param.set(k);

        Halide::Buffer<num_t> nrm_buf = col_sumsq.realize();
        num_t nrm = nrm_buf();

        // R[k][k] = sqrt(nrm);
        num_t rkk = SQRT_FUN(nrm);
        // R[row][col] -> R(col, row)
        R(k, k) = rkk;

        // Compute Q[:,k] = A[:,k] / R[k][k] with Halide.
        rkk_param.set(rkk);

        Halide::Buffer<num_t> qk_buf(m);
        q_col.realize(qk_buf);

        // Store into column k of Q: Q[i][k] -> Q(k, i)
        for (int i_idx = 0; i_idx < m; ++i_idx) {
            Q(k, i_idx) = qk_buf(i_idx);
        }

        // Bind Q for subsequent use.
        Q_param.set(Q);

        // Loop over j = k+1..n-1 on host; each column j is independent at fixed k.
        for (int j = k + 1; j < n; ++j) {
            j_param.set(j);

            // 3) Compute R[k][j] = sum_i Q[i][k] * A[i][j]
            A_param.set(A);

            Halide::Buffer<num_t> rkj_buf = dot_col.realize();
            num_t rkj = rkj_buf();

            // Store R[k][j] into R buffer: R[row][col] -> R(col, row)
            R(j, k) = rkj;

            // 4) Update A[:,j] = A[:,j] - Q[:,k] * R[k][j]
            rkj_param.set(rkj);

            Halide::Buffer<num_t> new_col(m);
            update_col.realize(new_col);

            // Write back updated column j into A: A[i][j] -> A(j, i)
            for (int i_idx = 0; i_idx < m; ++i_idx) {
                A(j, i_idx) = new_col(i_idx);
            }
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // ------------------------------------------------------------------------
    // Optionally print results (R and Q) to avoid dead-code elimination
    // and to match the style of the example gemm.cpp.
    // ------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print R: C code iterates i (row), j (col) and prints R[i][j].
        // Mapping: R[i][j] -> R(j, i).
        std::cerr << "R:\n";
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                std::cerr << R(j, i) << '\n';
            }
        }

        // Print Q: C code iterates i (row), j (col) and prints Q[i][j].
        // Mapping: Q[i][j] -> Q(j, i).
        std::cerr << "Q:\n";
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                std::cerr << Q(j, i) << '\n';
            }
        }
    }

    // Print timing in seconds (as in gemm.cpp).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
